 "content": "def transform(grid):
    """Recolor any fully uniform row or column to color 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        if len(set(grid[r])) == 1:
            out[r] = [2] * w
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            for r in range(h):
                out[r][c] = 2
    return out
